#!/usr/bin/env python3
import configparser
from pathlib import Path

import numpy as np
import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
LEGACY_DIR = BASE_DIR / "climate_analyzer"
CSV_PATH = LEGACY_DIR / "sample_data" / "climate_data.csv"
CONFIG_PATH = LEGACY_DIR / "config.ini"


def load_config(path):
    config = configparser.ConfigParser()
    config.read(path, encoding="utf-8")
    return config


def load_climate_data(path):
    return pd.read_csv(path, encoding="utf-8", parse_dates=["date"])


def report_station_means(df):
    grouped = df.groupby("station_id")["temperature"]
    for station_id, group in grouped:
        mean_temp = float(np.mean(group.values))
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


def main():
    config = load_config(CONFIG_PATH)
    baseline_years = config.get("analysis", "baseline_years", fallback="")
    if baseline_years:
        print(f"Baseline years: {baseline_years}")

    data = load_climate_data(CSV_PATH)
    report_station_means(data)


if __name__ == "__main__":
    main()
